261	app.post("/api/profiles/:username/follow", { preHandler: authMiddleware }, async (request: any, reply: any) => {
262	  const username = request.params.username as string;
263	  const target = await prisma.user.findUnique({
264	    where: { username },
265	    select: { id: true },
266	  });
267	  if (!target) {
268	    reply.code(404).send({ errors: { profile: ["not found"] } });
269	    return;
270	  }
271	  if (target.id === request.userId) {
272	    reply.code(422).send({ errors: { profile: ["can't follow yourself"] } });
273	    return;
274	  }
275	  await prisma.follow.upsert({
276	    where: { followerId_followingId: { followerId: request.userId, followingId: target.id } },
277	    create: { followerId: request.userId, followingId: target.id },
278	    update: {},
279	  });
280	  const profile = await prisma.user.findUnique({
281	    where: { username },
282	    select: { id: true, username: true, bio: true, image: true },
283	  });
284	  const isFollowing = await prisma.follow.findUnique({
285	    where: { followerId_followingId: { followerId: request.userId, followingId: target.id } },
286	  });
287	  return { profile: { ...profile, following: !!isFollowing } };
288	});
