291	app.delete("/api/profiles/:username/follow", { preHandler: authMiddleware }, async (request: any, reply: any) => {
292	  const username = request.params.username as string;
293	  const target = await prisma.user.findUnique({
294	    where: { username },
295	    select: { id: true },
296	  });
