462	app.put("/api/articles/:slug", { preHandler: authMiddleware }, async (request: any, reply: any) => {
463	  const slug = request.params.slug as string;
464	  const article = await prisma.article.findUnique({ where: { slug } });
465	  if (!article) {
466	    reply.code(404).send({ errors: { article: ["not found"] } });
467	    return;
468	  }
469	  if (article.authorId !== request.userId) {
470	    reply.code(403).send({ errors: { article: ["forbidden"] } });
471	    return;
472	  }
473	
474	  const body = request.body?.article || {};
475	  const updates: any = {};
476	  if (body.title !== undefined) updates.title = body.title;
477	  if (body.description !== undefined) updates.description = body.description;
478	  if (body.body !== undefined) updates.body = body.body;
479	
480	  // 태그 업데이트
481	  if (body.tagList !== undefined) {
482	    if (body.tagList === null) {
483	      reply.code(422).send({ errors: { article: ["tagList can't be blank"] } });
484	      return;
485	    }
486	    if (Array.isArray(body.tagList)) {
487	      await prisma.articleTag.deleteMany({ where: { articleId: article.id } });
488	      if (body.tagList.length > 0) {
489	        await prisma.articleTag.createMany({
490	          data: body.tagList.map((t: string) => ({ articleId: article.id, tag: t.toLowerCase() })),
491	        });
492	      }
493	    }
494	  }
495	
496	  // 슬러그 업데이트
497	  if (updates.title) {
498	    updates.slug = generateSlug(updates.title);
499	  }
500	
501	  const updated = await prisma.article.update({
502	    where: { id: article.id },
503	    data: updates,
504	    include: {
505	      author: { select: { id: true, username: true, bio: true, image: true } },
506	      tags: true,
507	      favorites: true,
508	    },
509	  });
510	  const updatedAuthor = updated.author as { id: number; username: string; bio: string | null; image: string | null };
511	  const isFollowing = await prisma.follow.findUnique({
512	    where: { followerId_followingId: { followerId: request.userId, followingId: updatedAuthor.id } },
513	    select: { id: true },
514	  });
515	  return {
516	    article: formatArticleResponse(
517	      { ...updated, author: { ...updatedAuthor, following: !!isFollowing } },
518	      false,
519	      updated.favorites.length,
520	    ),
521	  };
522	});
